        int m = grid.size(), n = grid[0].size();
        const int MOD = 1e9 + 7;
        vector<vector<vector<int>>> dp(m, vector<vector<int>>(n, vector<int>(16, 0)));
        dp[0][0][grid[0][0]] = 1;

        for (int i = 0; i < m; ++i) {
